mgc_code:
def sort_link(context, text, sort_field, visible_name=None):
    """Usage: {% sort_link "text" "field_name" %}
    Usage: {% sort_link "text" "field_name" "Visible name" %}
    """
    if visible_name is None:
        visible_name = text
    request = context['request']
    current_sort_field = request.GET.get('sort_by')
    current_sort_order = request.GET.get('sort_order', 'asc')
    if current_sort_field == sort_field:
        if current_sort_order == 'asc':
            sort_order = 'desc'
        else:
            sort_order = 'asc'
    else:
        sort_order = 'asc'
    new_query_params = request.GET.copy()
    new_query_params['sort_by'] = sort_field
    new_query_params['sort_order'] = sort_order
    new_url = request.path + '?' + new_query_params.urlencode()
    html = '<a href="{}" class="sort-link">{}</a>'.format(new_url, visible_name)
    return html

