def get_valid_statements_for_modeling(sts: List[Influence]) -> List[Influence]:
    """ Select INDRA statements that can be used to construct a Delphi model
    from a given list of statements. """
    valid_sts = []
    for st in sts:
        if st.is_modelable():
            valid_sts.append(st)
    return valid_sts

