mgc_code:
def dict_chunks(dictionary, chunk):
    """Return a list of dictionary with n-keys (chunk) per list."""
    result = []
    for key in dictionary:
        if not result or len(result[-1]) == chunk:
            result.append({})
        result[-1][key] = dictionary[key]
    return result

