def get_render(self, context):
        """
        Returns a `Context` object with all the necessary stuff for rendering the form

        :param context: `django.template.Context` variable holding the context for the node

        `self.form` and `self.helper` are resolved into real Python objects resolving them
        from the `context`. The `actual_form` can be a form or a formset. If it's a formset
        `is_formset` is set to True. If the helper has a layout we use it, for rendering the
        form or the formset's forms.
        """
        actual_form = self.form.resolve(context)
        actual_helper = self.helper.resolve(context)
        is_formset = False
        if actual_form.is_bound and hasattr(actual_form,'management_form'):
            is_formset = True
        if actual_helper.layout is not None:
            if is_formset:
                forms = []
                for form in actual_form:
                    forms.append(form.as_widget(actual_helper.layout))
                return Context({'forms': forms, 'is_formset': is_formset})
            else:
                return Context({'form': actual_form.as_widget(actual_helper.layout), 'is_formset': is_formset})
        else:
            if is_formset:
                forms = []
                for form in actual_form:
                    forms.append(form.as_p())
                return Context({'forms': forms, 'is_formset': is_formset})
            else:
                return Context({'form': actual_form.as_p(), 'is_formset': is_formset})

