def _find_id(self, result, uid):
        """
            This method performs a depth-first search for the given uid in the dictionary of results.
        """
        if uid in result:
            return result[uid]
        for child in result[self.root_id]['children']:
            if uid in child:
                return child[uid]
            else:
                return self._find_id(child, uid)

