        for field_name, field_type in cls.__fields__.items():
            if isinstance(field_type, TreeModel):
                fields.append(f"{field_name} {field_type.to_struct()}")
            else:
                fields.append(f"{field_name} {field_type}")
        struct_definition = f"struct {struct_name} {{\n"
        for field in fields:
            struct_definition += f"    {field};\n"
        struct_definition += "}"

        return struct_definition

