def moon_phase(self, date=None, rtype=int):
    if date is None:
        date = datetime.date.today()
    days_since_new_moon = (date - datetime.date(date.year, 1, 1)).days
    phase = math.floor(days_since_new_moon % 29.530588853)
    if rtype == int:
        return phase
    elif rtype == str:
        phases = ['New moon', 'First quarter', 'Full moon', 'Last quarter']
        return phases[phase // 7]
    else:
        raise ValueError('Invalid rtype')

