    if valid:
        if event.direction == Gdk.ScrollDirection.UP:
            direction = 0.0
        elif event.direction == Gdk.ScrollDirection.DOWN:
            direction = 180.0
        elif event.direction == Gdk.ScrollDirection.LEFT:
            direction = 270.0
        elif event.direction == Gdk.ScrollDirection.RIGHT:
            direction = 90.0

