def flag(self, payload):
        """Set a single flag on a resource.

        :param payload:
            t: can be one of make_public, make_private, make_shareable,
            make_not_shareable, make_discoverable, make_not_discoverable
        :return:
            empty but with 202 status_code
        """
        if payload['t'] =='make_public':
            self.is_public = True
        elif payload['t'] =='make_private':
            self.is_public = False
        elif payload['t'] =='make_shareable':
            self.is_shareable = True
        elif payload['t'] =='make_not_shareable':
            self.is_shareable = False
        elif payload['t'] =='make_discoverable':
            self.is_discoverable = True
        elif payload['t'] =='make_not_discoverable':
            self.is_discoverable = False
        return '', 202

