mgc_code:
def diffFromDefaults(theTask, report=False):
    """ Load the given file (or existing object), and return a dict
    of its values which are different from the default values.  If report
    is set, print to stdout the differences. """
    default_values = {
        'a': 1,
        'b': 2,
        'c': 3
    }
    if isinstance(theTask, dict):
        task_values = theTask
    else:
        task_values = vars(theTask)
    differences = {key: value for key, value in task_values.items() if key in default_values and value!= default_values[key]}
    if report:
        print("Differences from defaults:")
        for key, value in differences.items():
            print(f"{key}: {value}")
    return differences

