def _process_pair(first_fn, second_fn, error_protocol):
    """
    Look at given filenames, decide which is what and try to pair them.
    """
    if first_fn.endswith('.csv') and second_fn.endswith('.json'):
        return first_fn, second_fn
    elif first_fn.endswith('.json') and second_fn.endswith('.csv'):
        return second_fn, first_fn
    else:
        if error_protocol == 'raise':
            raise ValueError('Could not pair files')
        elif error_protocol == 'warn':
            print('Could not pair files')
        else:
            pass

