def sort_merge(in_file, data, out_dir=None):
    """Sort and merge a BED file, collapsing gene names.
       Output is a 3 or 4 column file (the 4th column values go comma-separated).
    """
    def sort_merge(in_file, data, out_dir=None):
        if out_dir is None:
            out_dir = tempfile.gettempdir()
        out_file = os.path.join(out_dir, os.path.basename(in_file))
        with open(out_file, 'w') as out_f:
            for line in data:
                out_f.write(line)
        subprocess.run(['sort', '-k1,1', '-k2,2n', in_file, out_file], stdout=out_file)
        with open(out_file, 'r') as in_f:
            prev_line = in_f.readline()
            for line in in_f:
                if line[:12] == prev_line[:12]:
                    prev_line = prev_line[:12] + ',' + line[12:]
                else:
                    yield prev_line
                    prev_line = line
        yield prev_line

