def query(hook=None,
          api_url=None,
          data=None):
    """
    Mattermost object method function to construct and execute on the API URL.
    :param api_url:     The Mattermost API URL
    :param hook:        The Mattermost hook.
    :param data:        The data to be sent for POST method.
    :return:            The json response from the API call or False.
    """
    def query(hook=None, api_url=None, data=None):
        if hook is None or api_url is None:
            return False
        if data is not None:
            data = json.dumps(data).encode('utf-8')
        request = urllib.request.Request(api_url, data=data)
        request.add_header('Content-Type', 'application/json')
        request.add_header('Authorization', f'Bearer {hook}')
        try:
            response = urllib.request.urlopen(request)
            return json.loads(response.read().decode('utf-8'))
        except urllib.error.HTTPError as e:
            return False

def fRD( a, M):
    """Calculate the ring-down frequency for the final Kerr BH. Using Eq. 5.5 of Main paper"""
    return 1 / (np.pi * M) * (1 + np.sqrt(1 - a**2))

